  let project=newProject(),selectedTrackId='',selectedClipIds=new Set(),selectedNoteIds=new Set(),playTick=0,playing=false,recording=false;
  let context=null,master=null,sources=new Set(),scheduler=0,raf=0,startedAt=0,startTick=0,nextEvent=0,events=[],drag=null,clipboard=null,midiAccess=null,openMidi=new Map(),recorded=[];
  const audioBuffers=new Map();
  const repository=new Repository(),commands=new Map(),manager=new CommandManager(label=>{markDirty(label);render()});let saveTimer=0;
  const activeTrack=()=>project.tracks.find(t=>t.id===selectedTrackId)||project.tracks[0];
  const activeClip=()=>{for(const t of project.tracks){const c=t.clips.find(x=>selectedClipIds.has(x.id));if(c)return{track:t,clip:c}}return null};
  const activeNote=()=>{const found=activeClip();return found?found.clip.notes.find(n=>selectedNoteIds.has(n.id)):null};
  const cloneClip=source=>{const copy=clone(source);if(source.blob)copy.blob=source.blob;return copy};
  const cloneProject=source=>{const copy=clone(source);source.tracks.forEach((track,index)=>track.clips.forEach((clip,clipIndex)=>{if(clip.blob)copy.tracks[index].clips[clipIndex].blob=clip.blob}));return copy};
  function snapTicks(tick){const value=$('d3Snap').value;if(value==='off')return Math.max(0,Math.round(tick));const map={'1':4,'1/2':2,'1/4':1,'1/8':.5,'1/16':.25,'1/32':.125},step=PPQ*map[value];return Math.max(0,Math.round(tick/step)*step)}
  function bpm(){return project.tempoMap[0]?.bpm||120}function beatsPerBar(){return project.timeSignatureMap[0]?.numerator||4}function totalTicks(){return Math.max(project.settings.bars*beatsPerBar()*PPQ,...project.tracks.flatMap(t=>t.clips.map(c=>c.startTick+c.lengthTicks)),PPQ*16)}
  function tickX(tick){return tick/PPQ*PX*project.settings.zoom}function xTick(x){return x/(PX*project.settings.zoom)*PPQ}
  function register(id,label,execute,enabled=()=>true,checked=()=>false){commands.set(id,{id,label,execute,enabled,checked})}
  function run(id,ctx={}){const command=commands.get(id);if(command?.enabled(ctx))command.execute(ctx);closeMenus()}
  function change(label,mutate,revert){manager.run(label,mutate,revert)}
  function markDirty(message='已修改'){project.updatedAt=Date.now();$('d3SaveState').textContent='未保存修改';$('d3Message').textContent=message;clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveProject(true),900)}
  async function saveProject(auto=false){try{$('d3SaveState').textContent=auto?'正在自动保存…':'正在保存…';await repository.put(project);$('d3SaveState').textContent='已保存 · '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}catch(error){$('d3SaveState').textContent='保存失败';$('d3Message').textContent=error.message}}
  function ensureAudio(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('浏览器不支持 Web Audio');if(!context||context.state==='closed'){context=new AC();master=context.createGain();const limiter=context.createDynamicsCompressor();limiter.threshold.value=-5;limiter.ratio.value=12;master.connect(limiter);limiter.connect(context.destination)}if(context.state==='suspended')context.resume();master.gain.value=project.master.mute?0:project.master.volume;return context}
  function audible(track){const anySolo=project.tracks.some(t=>t.solo);return!track.mute&&(!anySolo||track.solo)}
  function synth(event,track,when,duration){
    const c=ensureAudio(),gain=c.createGain(),pan=c.createStereoPanner(),filter=c.createBiquadFilter(),frequency=440*Math.pow(2,(event.pitch-69)/12),oscillators=[];
    pan.pan.value=track.pan;filter.type='lowpass';filter.frequency.value=6500;
    gain.gain.setValueAtTime(.0001,when);gain.gain.exponentialRampToValueAtTime(.16*(event.velocity/127)*track.volume,when+.008);gain.gain.exponentialRampToValueAtTime(.0001,when+duration);
    gain.connect(filter);filter.connect(pan);pan.connect(master);
    [[1,'triangle',1],[2,'sine',.27],[3,'sine',.1]].forEach(([ratio,type,level])=>{const osc=c.createOscillator(),g=c.createGain();osc.type=type;osc.frequency.value=frequency*ratio;g.gain.value=level;osc.connect(g);g.connect(gain);osc.start(when);osc.stop(when+duration+.04);oscillators.push(osc);sources.add(osc);osc.onended=()=>sources.delete(osc)});
    return {stop(at=c.currentTime){try{gain.gain.cancelScheduledValues(at);gain.gain.setTargetAtTime(.0001,at,.012)}catch(_){}oscillators.forEach(osc=>{try{osc.stop(at+.06)}catch(_){}})}};
  }
  function buildEvents(){const result=[];project.tracks.forEach(track=>{if(!audible(track))return;track.clips.forEach(clip=>{if(clip.muted)return;clip.notes.forEach(note=>{if(!note.muted)result.push({tick:clip.startTick+note.startTick,duration:note.durationTicks,note,track})})})});return result.sort((a,b)=>a.tick-b.tick)}
  async function prepareAudioBuffers(){const clips=project.tracks.flatMap(track=>track.clips).filter(clip=>clip.type==='audio'&&clip.blob&&!audioBuffers.has(clip.id));let done=0;for(const clip of clips){$('d3AudioLoad').textContent=`AUDIO ${Math.round(done/Math.max(1,clips.length)*100)}%`;const bytes=clip.blob instanceof Blob?await clip.blob.arrayBuffer():clip.blob;audioBuffers.set(clip.id,await ensureAudio().decodeAudioData(bytes.slice(0)));done++}$('d3AudioLoad').textContent='AUDIO READY'}
