  function updatePlayhead(){$('d3Playhead').style.left=tickX(playTick)+'px';const barTicks=beatsPerBar()*PPQ,bar=Math.floor(playTick/barTicks)+1,beat=Math.floor((playTick%barTicks)/PPQ)+1,sub=Math.floor(playTick%PPQ/PPQ*100);$('d3Position').textContent=`${String(bar).padStart(3,'0')}.${String(beat).padStart(2,'0')}.${String(sub).padStart(2,'0')}`;if(project.settings.follow&&playing){const x=tickX(playTick),arr=$('d3Arrange');if(x>arr.scrollLeft+arr.clientWidth*.8)arr.scrollLeft=x-arr.clientWidth*.3}}
  function render(){selectedTrackId||=project.tracks[0]?.id||'';$('d3ProjectName').textContent=project.name;$('d3Bpm').value=bpm();const meter=project.timeSignatureMap[0];$('d3Meter').value=`${meter.numerator}/${meter.denominator}`;$('d3Snap').value=project.settings.snap;$('d3Loop').classList.toggle('on',project.loop.enabled);$('d3Metro').classList.toggle('on',project.settings.metronome);renderRuler();renderTracks();renderLanes();renderEditor();renderInspector();updatePlayhead();$('d3Counts').textContent=`${project.tracks.length} TRACKS · ${project.tracks.reduce((sum,t)=>sum+t.clips.length,0)} CLIPS · ${project.tracks.reduce((sum,t)=>sum+t.clips.reduce((n,c)=>n+c.notes.length,0),0)} NOTES`}
