  function renderTracks(){$('d3Tracks').innerHTML=project.tracks.filter(t=>!t.hidden).map((t,index)=>`<div class="d3-track ${t.id===selectedTrackId?'selected':''}" data-track="${t.id}"><i class="d3-color" style="background:${t.color}"></i><span class="d3-track-name">${index+1} · ${esc(t.name)}</span><small>${t.type==='audio'?'AUDIO':'MIDI · CH '+t.midiChannel}</small><div class="d3-track-buttons"><button class="d3-mini ${t.mute?'on':''}" data-track-action="mute">M</button><button class="d3-mini ${t.solo?'on':''}" data-track-action="solo">S</button><button class="d3-mini rec ${t.armed?'on':''}" data-track-action="arm">R</button></div><input class="d3-slider" data-track-action="volume" type="range" min="0" max="120" value="${t.volume*100}"><label class="d3-pan">PAN <input class="d3-slider" data-track-action="pan" type="range" min="-100" max="100" value="${t.pan*100}"></label></div>`).join('')}
