  function updateNoteInspector(){const found=activeClip(),n=activeNote();if(!found||!n)return;n.pitch=clamp(+$('d3NotePitch').value,0,127);n.velocity=clamp(+$('d3NoteVelocity').value,1,127);n.startTick=Math.max(0,+$('d3NoteStart').value||0);n.durationTicks=Math.max(1,+$('d3NoteDuration').value||PPQ);markDirty();render()}
  function addTrack(type='instrument'){const t=newTrack(type==='audio'?`Audio ${project.tracks.length+1}`:`Instrument ${project.tracks.length+1}`,project.tracks.length,type);change(type==='audio'?'新建音频轨':'新建乐器轨',()=>{if(!project.tracks.some(x=>x.id===t.id))project.tracks.push(t);selectedTrackId=t.id},()=>{project.tracks=project.tracks.filter(x=>x.id!==t.id);selectedTrackId=project.tracks[0]?.id||''})}
