  function deleteSelection(){if(selectedNoteIds.size){const found=activeClip(),removed=found.clip.notes.filter(n=>selectedNoteIds.has(n.id)),indices=removed.map(n=>found.clip.notes.indexOf(n));change('删除音符',()=>{found.clip.notes=found.clip.notes.filter(n=>!selectedNoteIds.has(n.id));selectedNoteIds.clear()},()=>removed.forEach((n,i)=>found.clip.notes.splice(indices[i],0,n)));return}if(selectedClipIds.size){const removed=[];project.tracks.forEach(t=>t.clips.forEach((c,i)=>{if(selectedClipIds.has(c.id))removed.push({t,c,i})}));change('删除片段',()=>{project.tracks.forEach(t=>t.clips=t.clips.filter(c=>!selectedClipIds.has(c.id)));selectedClipIds.clear()},()=>removed.forEach(x=>x.t.clips.splice(x.i,0,x.c)))}}
  function duplicateClip(){const found=activeClip();if(!found)return;const copy=cloneClip(found.clip);copy.id=uid('clip');copy.name+=' 副本';copy.startTick+=copy.lengthTicks;copy.notes.forEach(n=>n.id=uid('note'));change('复制片段',()=>{if(!found.track.clips.some(c=>c.id===copy.id))found.track.clips.push(copy);selectedClipIds=new Set([copy.id])},()=>{found.track.clips=found.track.clips.filter(c=>c.id!==copy.id)})}
  function splitClip(){const found=activeClip();if(!found||playTick<=found.clip.startTick||playTick>=found.clip.startTick+found.clip.lengthTicks)return;const original=cloneClip(found.clip),cut=playTick-found.clip.startTick,right=cloneClip(found.clip);right.id=uid('clip');right.name+=' B';right.startTick=playTick;right.lengthTicks=found.clip.lengthTicks-cut;if(right.type==='audio')right.audioOffsetSeconds=(right.audioOffsetSeconds||0)+cut*(60/bpm()/PPQ);right.notes=right.notes.filter(n=>n.startTick>=cut).map(n=>({...n,id:uid('note'),startTick:n.startTick-cut}));change('分割片段',()=>{found.clip.lengthTicks=cut;found.clip.notes=found.clip.notes.filter(n=>n.startTick<cut);if(!found.track.clips.some(c=>c.id===right.id))found.track.clips.push(right);selectedClipIds=new Set([right.id]);if(audioBuffers.has(found.clip.id))audioBuffers.set(right.id,audioBuffers.get(found.clip.id))},()=>{Object.assign(found.clip,cloneClip(original));found.track.clips=found.track.clips.filter(c=>c.id!==right.id);audioBuffers.delete(right.id);selectedClipIds=new Set([found.clip.id])})}
  function quantizeNotes(){const found=activeClip();if(!found)return;const targets=selectedNoteIds.size?found.clip.notes.filter(n=>selectedNoteIds.has(n.id)):found.clip.notes,before=targets.map(n=>({id:n.id,start:n.startTick,dur:n.durationTicks}));const apply=()=>targets.forEach(n=>{n.startTick=snapTicks(n.startTick);n.durationTicks=Math.max(PPQ/8,snapTicks(n.durationTicks))});const revert=()=>before.forEach(item=>{const n=found.clip.notes.find(x=>x.id===item.id);if(n){n.startTick=item.start;n.durationTicks=item.dur}});change('量化音符',apply,revert)}
  function transpose(amount){const found=activeClip();if(!found)return;const targets=selectedNoteIds.size?found.clip.notes.filter(n=>selectedNoteIds.has(n.id)):found.clip.notes;change('移调',()=>targets.forEach(n=>n.pitch=clamp(n.pitch+amount,0,127)),()=>targets.forEach(n=>n.pitch=clamp(n.pitch-amount,0,127)))}
  function exportFile(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1200)}
  function waveformPeaks(buffer,count=72){const channel=buffer.getChannelData(0),step=Math.max(1,Math.floor(channel.length/count));return Array.from({length:count},(_,index)=>{let peak=0,start=index*step,end=Math.min(channel.length,start+step);for(let i=start;i<end;i++)peak=Math.max(peak,Math.abs(channel[i]));return Math.round(peak*1000)/1000})}
  async function importFiles(files){for(const file of files){if(!file.type.startsWith('audio/'))continue;const buffer=await ensureAudio().decodeAudioData((await file.arrayBuffer()).slice(0));let t=activeTrack();if(!t||t.type!=='audio'){t=newTrack(file.name.replace(/\.[^.]+$/,''),project.tracks.length,'audio');project.tracks.push(t)}const c=newClip(t.id,snapTicks(playTick),Math.max(PPQ/4,Math.round(buffer.duration/(60/bpm())*PPQ)));c.type='audio';c.name=file.name;c.blob=file.slice(0,file.size,file.type);c.audioDuration=buffer.duration;c.audioOffsetSeconds=0;c.waveform=waveformPeaks(buffer);c.notes=[];t.clips.push(c);audioBuffers.set(c.id,buffer);selectedTrackId=t.id;selectedClipIds=new Set([c.id]);markDirty('音频已导入')}render()}
  async function handleFile(file){if(!file)return;if(/\.json$/i.test(file.name)||file.type==='application/json'){project=migrate(JSON.parse(await file.text()));if(!project.tracks.length)project.tracks.push(newTrack('Instrument 1',0));manager.clear();selectedTrackId=project.tracks[0].id;selectedClipIds.clear();render();markDirty('已导入工程');return}const parsed=NS.midiFile.importMidi(await file.arrayBuffer());project=newProject(file.name.replace(/\.(mid|midi)$/i,''));project.tempoMap[0].bpm=Math.round(parsed.tempo);project.tracks=[];parsed.tracks.forEach((item,index)=>{const t=newTrack(item.name,index);item.region.trackId=t.id;t.clips=[item.region];project.tracks.push(t)});if(!project.tracks.length)project.tracks.push(newTrack('Instrument 1',0));selectedTrackId=project.tracks[0].id;manager.clear();markDirty('MIDI 导入完成');render()}
  function showOpen(){const recent=repository.recent();showModal(`<h2>打开工程</h2>${recent.length?recent.map(item=>`<p><button class="d3-btn" data-open-project="${item.id}">${esc(item.name)} · ${new Date(item.updatedAt).toLocaleString()}</button></p>`).join(''):'<p>暂无最近工程</p>'}`)}
  function showModal(html){$('d3Modal').innerHTML=`<div class="d3-modal-card">${html}<div class="d3-modal-actions"><button class="d3-btn" data-modal-close>关闭</button></div></div>`;$('d3Modal').classList.remove('hidden')}
  function closeModal(){$('d3Modal').classList.add('hidden')}
  function showContext(items,x,y,ctx){const menu=$('d3Context');menu.innerHTML=items.map(item=>item==='-'?'<hr>':`<button data-command="${item}" ${commands.get(item)?.enabled(ctx)?'':'disabled'}><span>${commands.get(item)?.label||item}</span></button>`).join('');menu.classList.remove('hidden');menu.tabIndex=-1;const rect=menu.getBoundingClientRect();menu.style.left=Math.max(4,Math.min(innerWidth-rect.width-4,x))+'px';menu.style.top=Math.max(4,Math.min(innerHeight-rect.height-4,y))+'px';menu._ctx=ctx;menu.querySelector('button:not(:disabled)')?.focus()}
  function closeMenus(){page.querySelectorAll('.d3-menu-wrap').forEach(m=>m.classList.remove('open'));$('d3Context').classList.add('hidden')}
  async function connectMidi(){if(!navigator.requestMIDIAccess){$('d3Midi').textContent='当前环境不支持 MIDI';return}try{midiAccess=await navigator.requestMIDIAccess({sysex:false});const bind=()=>midiAccess.inputs.forEach(input=>input.onmidimessage=handleMidi);bind();midiAccess.onstatechange=bind;$('d3Midi').textContent=`MIDI 已连接 (${midiAccess.inputs.size})`;$('d3Midi').classList.add('on')}catch(error){$('d3Message').textContent='MIDI 连接失败：'+error.message}}
  function handleMidi(event){const[data0,pitch,velocity]=event.data,cmd=data0&0xf0,key=`${data0&15}:${pitch}`;if(cmd===0x90&&velocity>0){const c=ensureAudio(),t=activeTrack();if(!t)return;const voice=synth({pitch,velocity},t,c.currentTime,8);openMidi.set(key,{pitch,velocity,at:c.currentTime,voice});if(recording)recorded.push({pitch,velocity,start:(c.currentTime-startedAt)/(60/bpm())*PPQ,duration:PPQ/4,key})}else if(cmd===0x80||(cmd===0x90&&velocity===0)){const open=openMidi.get(key);open?.voice?.stop();openMidi.delete(key);const rec=[...recorded].reverse().find(n=>n.key===key);if(rec)rec.duration=Math.max(PPQ/8,(context.currentTime-startedAt)/(60/bpm())*PPQ-rec.start)}}
